  document.documentElement.lang=lang==='zh'?'zh-CN':'en';document.title=t.title;$('headerLogo').src=lang==='zh'?'assets/logo-zh.png':'assets/logo-en.png';$('headerLogo').alt=lang==='zh'?'馒头AI':'MindDo.AI';
