function showToast(message,isError=false){const toast=$('toast');toast.textContent=message;toast.classList.toggle('error',isError);toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),2600)}
function safeFileName(name){return (name||'学生').replace(/[\\/:*?"<>|]/g,'-').trim()||'学生'}
function downloadCanvas(){draw();const button=$('downloadBtn');button.disabled=true;button.firstElementChild.textContent=lang==='zh'?'正在生成…':'Generating…';try{canvas.toBlob(blob=>{button.disabled=false;button.firstElementChild.textContent=ui[lang].download;if(!blob){showToast(lang==='zh'?'图片生成失败，请刷新页面后重试':'Image generation failed. Refresh and try again.',true);return}const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`${safeFileName($('studentName').value)}-${lang==='zh'?'试课反馈':'Trial-Feedback'}.png`;a.style.display='none';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);showToast(lang==='zh'?'图片已生成，请查看下载文件夹':'Image downloaded successfully.')},'image/png')}catch(error){button.disabled=false;button.firstElementChild.textContent=ui[lang].download;showToast(lang==='zh'?'图片生成失败，请刷新页面后重试':'Image generation failed. Refresh and try again.',true);console.error(error)}}
